-- ConnectionCyber — M10: restaurantes, lanchonetes, salão, comandas e cozinha.
begin;
create table public.erp_dining_areas(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,establishment_id uuid not null,code text not null,name text not null,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,establishment_id,code),unique(tenant_id,id),foreign key(tenant_id,establishment_id) references public.erp_establishments(tenant_id,id) on delete restrict);
create table public.erp_dining_tables(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,dining_area_id uuid not null,code text not null,name text not null,capacity integer not null check(capacity>0),status text not null default 'available' check(status in('available','occupied','cleaning','blocked')),qr_token_hash text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,dining_area_id,code),unique nulls not distinct(tenant_id,qr_token_hash),unique(tenant_id,id),foreign key(tenant_id,dining_area_id) references public.erp_dining_areas(tenant_id,id) on delete restrict);
create table public.erp_table_sessions(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,dining_table_id uuid not null,status text not null default 'open' check(status in('open','closing','closed','cancelled')),guest_count integer not null default 1 check(guest_count>0),opened_at timestamptz not null default now(),closed_at timestamptz,idempotency_key text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(tenant_id,idempotency_key),unique(tenant_id,id),foreign key(tenant_id,dining_table_id) references public.erp_dining_tables(tenant_id,id) on delete restrict,check((status in('closed','cancelled') and closed_at is not null)or status in('open','closing')));
create unique index erp_table_sessions_one_open on public.erp_table_sessions(tenant_id,dining_table_id)where status in('open','closing');
create table public.erp_table_session_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,table_session_id uuid not null,event_type text not null,from_status text,to_status text,notes text,idempotency_key text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(tenant_id,idempotency_key),unique(tenant_id,id),foreign key(tenant_id,table_session_id) references public.erp_table_sessions(tenant_id,id) on delete restrict);
create table public.erp_food_tabs(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,establishment_id uuid not null,table_session_id uuid,customer_id uuid,sale_id uuid,code text not null,channel text not null check(channel in('dine_in','counter','takeaway','delivery')),status text not null default 'open' check(status in('open','ordering','ready_to_close','closed','cancelled')),version integer not null default 1 check(version>0),guest_count integer not null default 1 check(guest_count>0),subtotal numeric(19,4) not null default 0 check(subtotal>=0),discount_total numeric(19,4) not null default 0 check(discount_total>=0),surcharge_total numeric(19,4) not null default 0 check(surcharge_total>=0),grand_total numeric(19,4) not null default 0 check(grand_total>=0),idempotency_key text not null,opened_at timestamptz not null default now(),closed_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,code),unique(tenant_id,idempotency_key),unique nulls not distinct(tenant_id,sale_id),unique(tenant_id,id),foreign key(tenant_id,establishment_id) references public.erp_establishments(tenant_id,id) on delete restrict,foreign key(tenant_id,table_session_id) references public.erp_table_sessions(tenant_id,id) on delete restrict,foreign key(tenant_id,customer_id) references public.erp_parties(tenant_id,id) on delete restrict,foreign key(tenant_id,sale_id) references public.erp_sales(tenant_id,id) on delete restrict,check((status='closed' and closed_at is not null and sale_id is not null)or status<>'closed'));
create table public.erp_food_tab_guests(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,food_tab_id uuid not null,guest_number integer not null check(guest_number>0),label text,created_at timestamptz not null default now(),unique(tenant_id,food_tab_id,guest_number),unique(tenant_id,id),foreign key(tenant_id,food_tab_id) references public.erp_food_tabs(tenant_id,id) on delete cascade);
create table public.erp_food_tab_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,food_tab_id uuid not null,event_type text not null,from_status text,to_status text,notes text,idempotency_key text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(tenant_id,idempotency_key),unique(tenant_id,id),foreign key(tenant_id,food_tab_id) references public.erp_food_tabs(tenant_id,id) on delete restrict);
create table public.erp_food_orders(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,food_tab_id uuid not null,round_number integer not null default 1 check(round_number>0),status text not null default 'draft' check(status in('draft','sent','preparing','ready','served','cancelled')),sent_at timestamptz,idempotency_key text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,idempotency_key),unique(tenant_id,food_tab_id,round_number),unique(tenant_id,id),foreign key(tenant_id,food_tab_id) references public.erp_food_tabs(tenant_id,id) on delete restrict);
create table public.erp_food_order_items(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,food_order_id uuid not null,guest_number integer,item_id uuid not null,variant_id uuid,unit_id uuid not null,stock_location_id uuid,recipe_composition_id uuid,item_code_snapshot text not null,description_snapshot text not null,status text not null default 'draft' check(status in('draft','queued','preparing','ready','served','cancelled','voided')),quantity numeric(19,6) not null check(quantity>0),unit_price numeric(19,4) not null check(unit_price>=0),discount_total numeric(19,4) not null default 0 check(discount_total>=0),line_total numeric(19,4) not null check(line_total>=0),notes text,idempotency_key text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,idempotency_key),unique(tenant_id,id),foreign key(tenant_id,food_order_id) references public.erp_food_orders(tenant_id,id) on delete restrict,foreign key(tenant_id,item_id) references public.erp_catalog_items(tenant_id,id) on delete restrict,foreign key(tenant_id,item_id,variant_id) references public.erp_item_variants(tenant_id,item_id,id) on delete restrict,foreign key(tenant_id,unit_id) references public.erp_units(tenant_id,id) on delete restrict,foreign key(tenant_id,stock_location_id) references public.erp_stock_locations(tenant_id,id) on delete restrict,foreign key(tenant_id,recipe_composition_id) references public.erp_item_compositions(tenant_id,id) on delete restrict,check(line_total=quantity*unit_price-discount_total));
create table public.erp_modifier_groups(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,code text not null,name text not null,min_selections integer not null default 0 check(min_selections>=0),max_selections integer not null default 1 check(max_selections>0),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,code),unique(tenant_id,id),check(max_selections>=min_selections));
create table public.erp_modifiers(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,modifier_group_id uuid not null,item_id uuid,code text not null,name text not null,price_delta numeric(19,4) not null default 0,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,modifier_group_id,code),unique(tenant_id,id),foreign key(tenant_id,modifier_group_id) references public.erp_modifier_groups(tenant_id,id) on delete restrict,foreign key(tenant_id,item_id) references public.erp_catalog_items(tenant_id,id) on delete restrict);
create table public.erp_food_order_item_modifiers(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,food_order_item_id uuid not null,modifier_id uuid not null,quantity numeric(19,6) not null default 1 check(quantity>0),price_delta_snapshot numeric(19,4) not null,line_total numeric(19,4) not null,created_at timestamptz not null default now(),unique(tenant_id,food_order_item_id,modifier_id),unique(tenant_id,id),foreign key(tenant_id,food_order_item_id) references public.erp_food_order_items(tenant_id,id) on delete cascade,foreign key(tenant_id,modifier_id) references public.erp_modifiers(tenant_id,id) on delete restrict,check(line_total=quantity*price_delta_snapshot));
create table public.erp_recipe_yields(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,composition_id uuid not null,version integer not null check(version>0),yield_quantity numeric(19,6) not null check(yield_quantity>0),yield_unit_id uuid not null,loss_percent numeric(7,4) not null default 0 check(loss_percent between 0 and 100),effective_from timestamptz not null default now(),effective_until timestamptz,created_at timestamptz not null default now(),unique(tenant_id,composition_id,version),unique(tenant_id,id),foreign key(tenant_id,composition_id) references public.erp_item_compositions(tenant_id,id) on delete restrict,foreign key(tenant_id,yield_unit_id) references public.erp_units(tenant_id,id) on delete restrict,check(effective_until is null or effective_until>effective_from));
create table public.erp_kitchen_stations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,establishment_id uuid not null,code text not null,name text not null,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,establishment_id,code),unique(tenant_id,id),foreign key(tenant_id,establishment_id) references public.erp_establishments(tenant_id,id) on delete restrict);
create table public.erp_kitchen_tickets(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,kitchen_station_id uuid not null,food_order_id uuid not null,code text not null,status text not null default 'queued' check(status in('queued','accepted','preparing','ready','dispatched','cancelled')),priority integer not null default 0,queued_at timestamptz not null default now(),started_at timestamptz,ready_at timestamptz,dispatched_at timestamptz,idempotency_key text not null,created_at timestamptz not null default now(),unique(tenant_id,idempotency_key),unique(tenant_id,code),unique(tenant_id,id),foreign key(tenant_id,kitchen_station_id) references public.erp_kitchen_stations(tenant_id,id) on delete restrict,foreign key(tenant_id,food_order_id) references public.erp_food_orders(tenant_id,id) on delete restrict);
create table public.erp_kitchen_ticket_items(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,kitchen_ticket_id uuid not null,food_order_item_id uuid not null,status text not null default 'queued' check(status in('queued','preparing','ready','dispatched','cancelled')),started_at timestamptz,ready_at timestamptz,created_at timestamptz not null default now(),unique(tenant_id,kitchen_ticket_id,food_order_item_id),unique(tenant_id,id),foreign key(tenant_id,kitchen_ticket_id) references public.erp_kitchen_tickets(tenant_id,id) on delete cascade,foreign key(tenant_id,food_order_item_id) references public.erp_food_order_items(tenant_id,id) on delete restrict);
create table public.erp_food_fulfillments(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,food_tab_id uuid not null,kind text not null check(kind in('table','counter','pickup','delivery')),status text not null default 'pending' check(status in('pending','ready','in_transit','delivered','cancelled')),promised_at timestamptz,completed_at timestamptz,address_snapshot jsonb,external_reference text,idempotency_key text not null,created_at timestamptz not null default now(),unique(tenant_id,idempotency_key),unique(tenant_id,id),foreign key(tenant_id,food_tab_id) references public.erp_food_tabs(tenant_id,id) on delete restrict);
create table public.erp_food_tab_splits(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,food_tab_id uuid not null,split_key text not null,method text not null check(method in('guest','item','amount')),amount numeric(19,4) not null check(amount>0),status text not null default 'planned' check(status in('planned','settled','cancelled')),idempotency_key text not null,created_at timestamptz not null default now(),unique(tenant_id,idempotency_key),unique(tenant_id,food_tab_id,split_key),unique(tenant_id,id),foreign key(tenant_id,food_tab_id) references public.erp_food_tabs(tenant_id,id) on delete restrict);

insert into public.erp_permissions(key,name,description,category)values('food.read','Consultar alimentação','Consulta salão, comandas e cozinha.','Alimentação'),('food.manage','Gerenciar salão','Mantém áreas, mesas e sessões.','Alimentação'),('food.order','Operar comandas','Cria comandas, pedidos e adicionais.','Alimentação'),('food.kitchen','Operar cozinha','Atualiza tickets e itens de cozinha.','Alimentação'),('food.cancel','Cancelar itens','Registra cancelamentos e contrapartidas.','Alimentação'),('food.discount','Autorizar descontos','Autoriza descontos e cortesias.','Alimentação'),('food.close','Fechar comandas','Converte comanda em venda M07.','Alimentação')on conflict(key)do update set name=excluded.name,description=excluded.description,category=excluded.category,active=true;

create or replace function public.erp_open_table_session(p_tenant_id uuid,p_dining_table_id uuid,p_guest_count integer,p_idempotency_key text)returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid;begin if not(erp_security.has_permission(p_tenant_id,'food.manage')or public.is_platform_staff())then raise exception 'permission denied';end if;select id into v_id from public.erp_table_sessions where tenant_id=p_tenant_id and idempotency_key=p_idempotency_key;if v_id is not null then return v_id;end if;if p_guest_count<=0 then raise exception 'invalid guest count';end if;perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||p_dining_table_id::text,0));if exists(select 1 from public.erp_table_sessions where tenant_id=p_tenant_id and dining_table_id=p_dining_table_id and status in('open','closing'))then raise exception 'table occupied';end if;insert into public.erp_table_sessions(tenant_id,dining_table_id,guest_count,idempotency_key,created_by)values(p_tenant_id,p_dining_table_id,p_guest_count,p_idempotency_key,auth.uid())returning id into v_id;update public.erp_dining_tables set status='occupied',updated_at=now()where tenant_id=p_tenant_id and id=p_dining_table_id;return v_id;end $$;
create or replace function public.erp_close_food_tab(p_tenant_id uuid,p_food_tab_id uuid,p_expected_version integer,p_idempotency_key text)returns uuid language plpgsql security definer set search_path='' as $$ declare v_tab public.erp_food_tabs%rowtype;v_sale uuid;v_sub numeric(19,4);v_disc numeric(19,4);v_mod numeric(19,4);v_total numeric(19,4);v_split numeric(19,4);begin if not(erp_security.has_permission(p_tenant_id,'food.close')or public.is_platform_staff())then raise exception 'permission denied';end if;perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||p_food_tab_id::text,0));select * into v_tab from public.erp_food_tabs where tenant_id=p_tenant_id and id=p_food_tab_id for update;if not found then raise exception 'food tab not found';end if;if v_tab.status='closed'then return v_tab.sale_id;end if;if v_tab.status<>'ready_to_close'or v_tab.version<>p_expected_version or v_tab.idempotency_key<>p_idempotency_key then raise exception 'tab not ready or version mismatch';end if;if exists(select 1 from public.erp_food_orders where tenant_id=p_tenant_id and food_tab_id=v_tab.id and status not in('served','cancelled'))then raise exception 'unfinished orders';end if;select coalesce(sum(i.quantity*i.unit_price),0),coalesce(sum(i.discount_total),0),coalesce(sum(i.line_total),0)into v_sub,v_disc,v_total from public.erp_food_order_items i join public.erp_food_orders o on o.tenant_id=i.tenant_id and o.id=i.food_order_id where o.tenant_id=p_tenant_id and o.food_tab_id=v_tab.id and i.status not in('cancelled','voided');select coalesce(sum(m.line_total),0)into v_mod from public.erp_food_order_item_modifiers m join public.erp_food_order_items i on i.tenant_id=m.tenant_id and i.id=m.food_order_item_id join public.erp_food_orders o on o.tenant_id=i.tenant_id and o.id=i.food_order_id where o.tenant_id=p_tenant_id and o.food_tab_id=v_tab.id and i.status not in('cancelled','voided');v_total:=v_total+v_mod;if v_total<=0 or v_total<>v_sub-v_disc+v_mod then raise exception 'invalid totals';end if;select coalesce(sum(amount),0)into v_split from public.erp_food_tab_splits where tenant_id=p_tenant_id and food_tab_id=v_tab.id and status='planned';if v_split<>0 and v_split<>v_total then raise exception 'split mismatch';end if;select id into v_sale from public.erp_sales where tenant_id=p_tenant_id and idempotency_key=p_idempotency_key||':sale';if v_sale is null then insert into public.erp_sales(tenant_id,establishment_id,customer_id,code,status,subtotal,discount_total,surcharge_total,grand_total,idempotency_key,created_by)values(p_tenant_id,v_tab.establishment_id,v_tab.customer_id,v_tab.code||'-VENDA','draft',v_sub,v_disc,v_mod,v_total,p_idempotency_key||':sale',auth.uid())returning id into v_sale;insert into public.erp_sale_items(tenant_id,sale_id,item_id,variant_id,unit_id,stock_location_id,item_code_snapshot,description_snapshot,quantity,unit_price,discount_total,surcharge_total,line_total)select i.tenant_id,v_sale,i.item_id,i.variant_id,i.unit_id,i.stock_location_id,i.item_code_snapshot,i.description_snapshot,i.quantity,i.unit_price,i.discount_total,coalesce((select sum(m.line_total)from public.erp_food_order_item_modifiers m where m.tenant_id=i.tenant_id and m.food_order_item_id=i.id),0),i.line_total+coalesce((select sum(m.line_total)from public.erp_food_order_item_modifiers m where m.tenant_id=i.tenant_id and m.food_order_item_id=i.id),0)from public.erp_food_order_items i join public.erp_food_orders o on o.tenant_id=i.tenant_id and o.id=i.food_order_id where o.tenant_id=p_tenant_id and o.food_tab_id=v_tab.id and i.status not in('cancelled','voided');end if;update public.erp_food_tabs set status='closed',sale_id=v_sale,subtotal=v_sub,discount_total=v_disc,surcharge_total=v_mod,grand_total=v_total,closed_at=now(),version=version+1,updated_at=now()where tenant_id=p_tenant_id and id=v_tab.id;insert into public.erp_food_tab_events(tenant_id,food_tab_id,event_type,from_status,to_status,idempotency_key,created_by)values(p_tenant_id,v_tab.id,'closed','ready_to_close','closed',p_idempotency_key||':event',auth.uid())on conflict(tenant_id,idempotency_key)do nothing;if v_tab.table_session_id is not null then update public.erp_table_sessions set status='closed',closed_at=now()where tenant_id=p_tenant_id and id=v_tab.table_session_id;update public.erp_dining_tables d set status='cleaning',updated_at=now()from public.erp_table_sessions s where s.tenant_id=p_tenant_id and s.id=v_tab.table_session_id and d.tenant_id=s.tenant_id and d.id=s.dining_table_id;end if;return v_sale;end $$;

do $$ declare t text;begin foreach t in array array['erp_dining_areas','erp_dining_tables','erp_table_sessions','erp_table_session_events','erp_food_tabs','erp_food_tab_guests','erp_food_tab_events','erp_food_orders','erp_food_order_items','erp_modifier_groups','erp_modifiers','erp_food_order_item_modifiers','erp_recipe_yields','erp_kitchen_stations','erp_kitchen_tickets','erp_kitchen_ticket_items','erp_food_fulfillments','erp_food_tab_splits']loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I on public.%I for select to authenticated using ((select erp_security.has_permission(tenant_id,''food.read''))or(select erp_security.has_permission(tenant_id,''food.manage''))or(select erp_security.has_permission(tenant_id,''food.order''))or(select erp_security.has_permission(tenant_id,''food.kitchen''))or(select public.is_platform_staff()))',t||'_select',t);execute format('create policy %I on public.%I for insert to authenticated with check ((select erp_security.has_permission(tenant_id,''food.manage''))or(select erp_security.has_permission(tenant_id,''food.order''))or(select erp_security.has_permission(tenant_id,''food.kitchen''))or(select public.is_platform_staff()))',t||'_insert',t);execute format('revoke all on table public.%I from anon,authenticated',t);execute format('grant select,insert on table public.%I to authenticated',t);execute format('grant all on table public.%I to service_role',t);end loop;end $$;
do $$ declare t text;begin foreach t in array array['erp_dining_areas','erp_dining_tables','erp_food_tabs','erp_food_orders','erp_food_order_items','erp_modifier_groups','erp_modifiers','erp_kitchen_stations','erp_kitchen_tickets','erp_kitchen_ticket_items','erp_food_fulfillments']loop execute format('create policy %I on public.%I for update to authenticated using ((select erp_security.has_permission(tenant_id,''food.manage''))or(select erp_security.has_permission(tenant_id,''food.order''))or(select erp_security.has_permission(tenant_id,''food.kitchen''))or(select public.is_platform_staff())) with check ((select erp_security.has_permission(tenant_id,''food.manage''))or(select erp_security.has_permission(tenant_id,''food.order''))or(select erp_security.has_permission(tenant_id,''food.kitchen''))or(select public.is_platform_staff()))',t||'_update',t);execute format('grant update on table public.%I to authenticated',t);end loop;end $$;
revoke execute on function public.erp_open_table_session(uuid,uuid,integer,text),public.erp_close_food_tab(uuid,uuid,integer,text)from public,anon;
grant execute on function public.erp_open_table_session(uuid,uuid,integer,text),public.erp_close_food_tab(uuid,uuid,integer,text)to authenticated,service_role;
commit;
